// Loop over input items
for (const item of $input.all()) {
  // Check if metrics exists and is a string
  if (item.json.metrics && typeof item.json.metrics === 'string') {
    try {
      // Parse the stringified JSON into a real Object
      const parsedMetrics = JSON.parse(item.json.metrics);

      // Update the metrics field with the parsed object
      item.json.metrics = parsedMetrics;

    } catch (error) {
      // Optional: Log error if parsing fails, but keep flow going
      console.log('Error parsing metrics JSON for item', item.index);
    }
  }
}

return $input.all();

